F2 = [['owner alice → bob', '拒绝:创建后不可修改'], ['只改 max', '通过'], ['tier dev → prod', '通过'], ['tier prod → dev', '拒绝:不能降级'], ['新增 owner', 'oldSelf 不存在,规则不执行']]
F3 = [['无 maxItems / maxLength', 'CRD 创建被拒:成本超预算 100 倍'], ['加 maxItems 20 + maxLength 20', 'CRD 创建成功'], ['[a, b, a]', '规则拒绝:names 里有重复'], ['25 个元素', 'schema 拒绝:Too many'], ['messageExpression 里 string(int)', '也被判成本超预算']]
PANELS = [('f', 'flow', 'CRD 的 CEL 校验'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("CRD 的 spec 上两条规则:self.min <= self.max(message: min 不能大于 max,fieldPath: .max)和 !has(self.mode) || self.mode != 'strict' || self.max <= 100(messageExpression 拼出消息)。min=1 max=10 通过;min=20 max=10 被拒:The Range \"bad\" is invalid: spec.max: Invalid value: min 不能大于 max(错误挂在 fieldPath 指的 .max 上);mode=strict max=500 被拒:spec: Invalid value: strict 模式下 max 不能超过 100(mode=strict);两条同时违反时一次列出两条;不写 mode 时 has() 保护了规则,创建通过。", f=fl(F1, cur=[1, 2, 3], done=[0, 4]), t=tl(S(1), mark=lidx(S(1), 'min=20 max=10', 'mode=strict max=500', '两条规则同时违反'), done=lidx(S(1), 'min=1 max=10', '不写 mode')), kv=KV([['self', '当前对象(或字段)'], ['fieldPath', '把错误挂到更具体的字段上'], ['has()', '可选字段先判断存在再用']], ['self'])),
    step("迁移规则用 oldSelf:owner 的规则 self == oldSelf,把 alice 改成 bob 被拒(spec.owner: Invalid value: \"bob\": owner 创建后不可修改);只改 max 通过;tier 的规则 oldSelf != 'prod' || self == 'prod':dev → prod 通过,prod → dev 被拒(prod 不能降级)。创建时没有 owner 的对象,之后第一次设置 owner 通过——oldSelf 不存在时迁移规则不会执行。", f=fl(F2, cur=[0, 3], done=[1, 2, 4]), t=tl(S(2), mark=lidx(S(2), 'alice 改成 bob', 'prod → dev'), done=lidx(S(2), '只改 max', 'dev → prod', '第一次设置')), kv=KV([['oldSelf', '更新前的值,只在 UPDATE 时有'], ['创建时不执行', '没有旧值就不比较'], ['不可变字段', 'self == oldSelf 的标准写法']], ['oldSelf'])),
    step("没有上限的数组和字符串会让 CRD 本身被拒:names 是没有 maxItems 的数组、元素是没有 maxLength 的字符串,规则 self.all(x, self.exists_one(y, x == y)):CRD 创建失败,estimated rule cost exceeds budget by factor of more than 100x (try simplifying the rule, or adding maxItems, maxProperties, and maxLength …)。加上 maxItems: 20 和 maxLength: 20 后创建成功;names: [a, b, a] 被规则拒绝(names 里有重复);25 个元素被 schema 拒绝(Too many: 25: must have at most 20 items)。另一个意外:messageExpression 里写 string(self.max) 把整数转字符串拼进消息,同样被判成本超预算。", f=fl(F3, cur=[0, 4], done=[1, 2, 3]), t=tl(S(3), mark=lidx(S(3), 'list 没有 maxItems', '另一个意外'), done=lidx(S(3), '加上 maxItems', 'names: [a, b, a]', '25 个元素')), kv=KV([['成本预算', '创建 CRD 时静态估算,太贵直接拒绝'], ['maxItems / maxLength', '给集合和字符串设上限,估算才可控'], ['简单表达式', '避免嵌套遍历(all + exists_one)']], ['成本预算'])),
]
A = mkartk('k88', 88, 'Kubernetes,CRD,CEL,x-kubernetes-validations,准入,校验,真实验证,动画演示',
    '在 kind 集群里给 CRD 写 x-kubernetes-validations:跨字段规则 self.min <= self.max 用 fieldPath 把错误挂到 .max,messageExpression 拼出提示,两条违反时一次列出;用 oldSelf 写迁移规则实现 owner 创建后不可改、tier 不能从 prod 降级,新增字段时不执行;没有 maxItems / maxLength 的数组加嵌套遍历规则会让 CRD 创建就被拒(成本超预算 100 倍),连 messageExpression 里的 string(整数) 也会被判超预算。',
    '不用 webhook,怎么给 CRD 加上“min 不能大于 max”这类跨字段校验?怎么让字段创建后不可修改?为什么有的 CEL 规则连 CRD 都创建不了?这篇用一个 Range 资源把规则、迁移规则和成本限制各自跑一遍。',
    [('oldSelf', 'CEL 里引用更新前的值,实现“创建后不可变”“不能降级”等迁移规则'), ('>100x', '规则的静态估算成本超出预算 100 倍时,CRD 创建就被拒绝'), ('has()', '可选字段上的规则需要 has(self.x) 保护,否则字段缺失时规则出错')],
    [('跨字段规则', '<p>CRD 的 <code>spec</code> 上两条规则:<code>self.min &lt;= self.max</code>(<code>message: min 不能大于 max</code>,<code>fieldPath: .max</code>)和 <code>!has(self.mode) || self.mode != \'strict\' || self.max &lt;= 100</code>(<code>messageExpression</code> 拼出消息)。<code>min=1 max=10</code> 通过;<code>min=20 max=10</code> 被拒:<code>The Range "bad" is invalid: spec.max: Invalid value: min 不能大于 max</code>——错误挂在 <code>fieldPath</code> 指的 <code>.max</code> 上;<code>mode=strict max=500</code> 被拒;两条同时违反时一次列出两条;不写 <code>mode</code> 时,<code>has()</code> 保护了规则,创建通过。</p>'),
     ('迁移规则', '<p><code>oldSelf</code> 是更新前的值,只在 UPDATE 时存在。<code>owner</code> 的规则 <code>self == oldSelf</code>:把 alice 改成 bob 被拒(<code>spec.owner: Invalid value: "bob": owner 创建后不可修改</code>),只改 <code>max</code> 通过。<code>tier</code> 的规则 <code>oldSelf != \'prod\' || self == \'prod\'</code>:dev → prod 通过,prod → dev 被拒(<code>prod 不能降级</code>)。创建时没有 <code>owner</code> 的对象,之后第一次设置 <code>owner</code> 通过——<code>oldSelf</code> 不存在时迁移规则不执行。</p>'),
     ('成本限制', '<p>没有上限的数组和字符串会让 CRD 本身被拒:<code>names</code> 是没有 <code>maxItems</code> 的数组、元素是没有 <code>maxLength</code> 的字符串,规则 <code>self.all(x, self.exists_one(y, x == y))</code>:CRD 创建失败,<code>estimated rule cost exceeds budget by factor of more than 100x (try simplifying the rule, or adding maxItems, maxProperties, and maxLength …)</code>。加上 <code>maxItems: 20</code> 和 <code>maxLength: 20</code> 后创建成功;<code>names: [a, b, a]</code> 被规则拒绝(<code>names 里有重复</code>);25 个元素被 schema 拒绝(<code>Too many: 25: must have at most 20 items</code>)。还有一个意外:<code>messageExpression</code> 里写 <code>string(self.max)</code> 把整数转字符串拼进消息,同样被判成本超预算(用 <code>self.mode</code> 这样有 <code>maxLength</code> 的字符串就没问题)。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);自建 CRD ranges.k88.example.com 与 namesets.k88.example.com(kind 起初叫 List,与内置 List 冲突后改名 NameSet);对象用 kubectl apply / patch 提交;成本限制的报错来自创建 CRD 的 API 响应;每种情形各一次',
     '没有验证:optionalOldSelf;ratcheting validation(旧值已违反规则时放行未改动字段);扩展库 URL、quantity 等 CEL 函数;规则里的 reason 字段(FieldValueForbidden / FieldValueRequired 等)对 HTTP 状态的影响;listType=map 与唯一性规则的配合;string(int) 为什么被估算为超预算(推测与整数转字符串的长度估算有关)'],
    'CRD CEL 校验', PANELS)
